# ================================================================ OA 25 · clase 5
L(OA25, 5,
  "Este cuaderno, lápiz y una hoja. Los avisos son inventados y vienen escritos.",
  "Aprenderé a evaluar críticamente un aviso: reconocer sus recursos persuasivos y juzgar si sus afirmaciones tienen pruebas. Sirve para decidir con criterio y no por impulso.",
  ["Sé analizar emisor, intención y destinatario.", "Sé qué es un fundamento."],
  ["Evaluar críticamente es analizar un aviso con preguntas y juzgar si es confiable, sin rechazarlo ni aceptarlo de entrada. Los avisos usan recursos persuasivos: la exageración («el mejor del mundo»), la oferta («dos por uno»), la urgencia («solo hoy»), el regalo («dinosaurio de regalo»), el testimonio o la estadística («cuatro de cada cinco») y las emociones.",
   "Para evaluar, pregunta: ¿tiene pruebas lo que afirma?, ¿dice de dónde sale el dato?, ¿qué información importante no entrega (el precio, los ingredientes, los riesgos)? «Cuatro de cada cinco familias lo prefieren» suena fuerte, pero no dice quién preguntó, a cuántas familias ni cuándo. «El mejor del mundo» no se puede comprobar.",
   "Tu evaluación se escribe con razones: «El aviso es poco confiable, porque dice “el mejor del mundo” sin dar pruebas». Una opinión sin razón no es crítica. Evaluar críticamente no es decir que toda la publicidad es mala; es leerla con atención y decidir con información."],
  [("evaluar", "juzgar con razones"), ("exageración", "afirmar algo mucho más grande de lo real"), ("urgencia", "presión por decidir rápido"), ("estadística", "dato numérico sobre un grupo"), ("fuente", "origen de un dato"), ("confiable", "que merece confianza")],
  [("Reconocer recursos", f"Lee o escucha: {PAN} ¿Qué recursos persuasivos usa?", ["«El mejor pan del mundo» es exageración.", "«Solo hoy» crea urgencia.", "«Dos por el precio de uno» es una oferta."], "Exageración, urgencia y oferta."),
   ("Evaluar con razones", f"Lee o escucha: {JUGO} Evalúa la afirmación «Cuatro de cada cinco familias lo prefieren».", ["Veo que da una cifra.", "No dice quién la midió ni a cuántas familias.", "Concluyo que es poco confiable."], "Es poco confiable, porque no dice quién hizo la encuesta ni a cuántas familias.")],
  [("Decir «me gusta» o «es malo» sin razones.", "No es una evaluación crítica.", "Agrega «porque» y un dato del aviso."),
   ("Creer un dato solo porque es numérico.", "Un número sin fuente no prueba nada.", "Pregunta de dónde sale.")],
  ([E(f"Lee o escucha: {PAN} ¿Qué frase es una exageración?", "«El mejor pan del mundo»", "No se puede comprobar."),
    E(f"Lee o escucha: {PAN} ¿Qué frase crea urgencia?", "«Solo hoy»", "Presiona para decidir rápido."),
    E(f"Lee o escucha: {JUGO} ¿Qué dato falta para confiar en «Cuatro de cada cinco familias»?", "Quién hizo la encuesta", "Falta la fuente.")],
   [E("¿Qué es un recurso persuasivo?", "Una herramienta para convencer", "Busca que el público actúe."),
    E(f"Lee o escucha: {PAN} ¿«Dos por el precio de uno» es una oferta?", "Sí", "Ofrece un beneficio económico."),
    E(f"Lee o escucha: {JUGO} Para que «Cuatro de cada cinco» sea confiable, ¿qué necesita: la fuente y cuántas familias se consultaron o más colores?", "La fuente y cuántas familias se consultaron", "Sin eso no se puede verificar.")],
   [E(f"Lee o escucha: {ZAP} «Corre más rápido que tus amigos», ¿es una promesa comprobable?", "No", "Es una exageración sin pruebas."),
    E(f"Lee o escucha: {CER} «Colecciona los seis», ¿qué busca el emisor?", "Que compren varias cajas", "Se necesita comprar varias veces para completar la colección."),
    E(f"Lee o escucha: {PAN} ¿Qué evaluación está mejor fundamentada? A: «El aviso es poco confiable, porque dice “el mejor del mundo” sin pruebas». B: «Me gustó».", "A", "Da una razón tomada del aviso.")],
   [E("Un compañero dice: «El aviso tiene un dibujo bonito, así que dice la verdad». ¿Tiene razón?", "No", "La belleza no prueba la veracidad."),
    E("¿Evaluar críticamente es decir que todo aviso es malo?", "No", "Es analizar con razones.")],
   [E(f"Lee o escucha: {PAN} ¿Cuántos tipos distintos de recursos persuasivos (exageración, urgencia, oferta, regalo, estadística) aparecen en el aviso?", "3", "Aparecen exageración, urgencia y oferta."),
    E(f"Lee o escucha: {PAN} ¿Qué dato no entrega el aviso: el precio del pan o que hay una oferta?", "El precio del pan", "Habla de la oferta, pero no dice cuánto cuesta.")]),
  [E(f"Lee o escucha: {ZAP} Quieres evaluarlo. ¿Qué pregunta ayuda más: «¿tiene pruebas la promesa de correr más rápido?» o «¿de qué color es el afiche?»?", "«¿Tiene pruebas la promesa de correr más rápido?»", "Apunta a la confiabilidad del mensaje.")],
  [E("¿«Solo hoy» crea urgencia o confianza?", "Urgencia", "Presiona para comprar rápido."),
   E("¿Un dato sin fuente es confiable?", "No", "No se puede verificar."),
   E("¿Una evaluación crítica debe tener razones?", "Sí", "Sin razones no es crítica.")],
  ("Evalúa críticamente este aviso con cuatro oraciones: emisor, intención, destinatario y un juicio con una razón. Aviso: «Revista juvenil. Gorros Cumbre, los más abrigados del mundo. Compra uno hoy y llévate gratis una bufanda. ¡Solo esta semana!».",
   "Emisor: la marca Gorros Cumbre. Intención: vender gorros. Destinatario: jóvenes, por la revista juvenil. Juicio: es poco confiable, porque dice «los más abrigados del mundo» sin pruebas, y usa urgencia con «solo esta semana».",
   ["identifica los tres pasos", "da un juicio", "da una razón del aviso"], ["cuatro oraciones"], ["no fundamentar", "aceptar todo sin pensar"],
   "Pide señalar la frase que usó como evidencia."),
  "Busca una exageración en un aviso de tu casa.",
  "Escribe una pregunta para cada recurso persuasivo de esta clase que sirva para evaluarlo.")

# ================================================================ OA 25 · clase 6
L(OA25, 6,
  "Este cuaderno, lápiz y una hoja. Los avisos y el borrador de evaluación vienen escritos.",
  "Aprenderé a distinguir la publicidad comercial de la social y a revisar una evaluación crítica para que esté bien fundamentada. Sirve para comunicar mi análisis con claridad a otra persona.",
  ["Sé evaluar un aviso con cuatro pasos.", "Sé identificar recursos persuasivos."],
  ["La publicidad comercial quiere vender; la social busca el bien común, como lavarse las manos o cruzar por la cebra. La social también persuade, pero su emisor suele ser una institución pública u organización, y no ofrece un producto para comprar. Aun así, hay que analizarla: ¿quién la emite?, ¿qué conducta busca?, ¿a quién se dirige?",
   "Una evaluación escrita debe tener cuatro partes: emisor, intención, destinatario y fundamento. Revisarla significa comprobar que cada parte esté y que las conclusiones se apoyen en pistas del aviso. Un borrador como «El aviso es bueno porque es bonito» no sirve: no dice nada de las cuatro partes.",
   "Al revisar para otra persona, usa frases claras: «El emisor es...», «Su intención es...», «Se dirige a... porque...». Elimina opiniones sin razón y agrega la pista que falta. Una buena evaluación puede leerse sin tener el aviso al lado."],
  [("publicidad social", "la que busca el bien común"), ("conducta", "forma de actuar"), ("institución", "organización pública o privada con fines definidos"), ("borrador", "primera versión de un texto"), ("revisar", "mejorar un texto comprobando sus partes"), ("fundamento", "razón o prueba que respalda lo que digo")],
  [("Publicidad social", f"Lee o escucha: {LAVADO} ¿Quién la emite y qué conducta busca?", ["La emite un consultorio.", "No vende nada.", "Busca que las personas se laven las manos."], "Emisor: el consultorio. Conducta: lavarse las manos 20 segundos."),
   ("Revisar un borrador", "Borrador: «El aviso de la municipalidad es bueno porque es bonito». ¿Qué falta?", ["No dice el emisor completo ni la intención.", "No menciona el destinatario.", "No da pistas del aviso."], "Faltan emisor, intención, destinatario y fundamentos.")],
  [("Evaluar solo con «es bonito» o «es feo».", "No se analiza el mensaje.", "Usa las cuatro partes y pistas."),
   ("Entregar la evaluación sin releer.", "Se pasan errores o faltas de datos.", "Revísala con una lista de verificación.")],
  ([E(f"Lee o escucha: {LAVADO} ¿Quién emite el mensaje?", "El Consultorio de Villa Ejemplo", "Lo dice la primera oración."),
    E(f"Lee o escucha: {LAVADO} ¿Qué conducta busca?", "Que las personas se laven las manos", "Es la acción que pide."),
    E(f"Lee o escucha: {LAVADO} ¿Cuántos segundos se recomienda lavarse las manos?", "20 segundos", "Lo dice el aviso.")],
   [E("¿Qué diferencia hay entre publicidad comercial y social: la comercial busca vender y la social el bien común?", "Sí", "Esa es su diferencia principal."),
    E(f"Lee o escucha: {LAVADO} ¿La publicidad social también persuade?", "Sí", "Busca cambiar una conducta."),
    E(f"Lee o escucha: {LAVADO} ¿Vende algún producto?", "No", "No ofrece nada para comprar.")],
   [E("Borrador: «El aviso es bueno porque es bonito». ¿Qué le falta para estar fundamentado: una razón basada en el aviso o más adjetivos?", "Una razón basada en el aviso", "Ser bonito no fundamenta la evaluación."),
    E(f"Lee o escucha: {LAVADO} ¿Qué pista muestra que se dirige también a niños: la imagen de un niño lavándose las manos o la palabra «agua»?", "La imagen de un niño lavándose las manos", "Muestra a un niño como protagonista."),
    E(f"Lee o escucha: {MUN} Borrador: «El emisor es la municipalidad; busca que crucemos por la cebra; se dirige a peatones». ¿Qué falta?", "El fundamento: cómo llegó a esa conclusión", "Faltan las pistas del aviso.")],
   [E("Un revisor dice que la evaluación debe tener una opinión sin razones. Otro dice que debe tener razones. ¿Quién tiene razón?", "El que dice que debe tener razones", "Una evaluación crítica se fundamenta."),
    E(f"Lee o escucha: {LAVADO} ¿Se puede afirmar con el aviso que el consultorio quiere ganar dinero?", "No", "El aviso no ofrece ni vende nada.")],
   [E("Ordena las partes de una evaluación completa: emisor, intención, destinatario y fundamento. ¿Cuál es el orden?", "Emisor, intención, destinatario y fundamento", "Es el método de análisis."),
    E(f"Lee o escucha: {MUN} {LAVADO} Ambos son publicidad social. ¿Qué buscan en común: cambiar una conducta o vender un producto?", "Cambiar una conducta", "Ninguno vende nada.")]),
  [E("Debes entregar tu evaluación a otro curso. ¿Qué es mejor: revisarla con una lista de las cuatro partes o entregarla sin leerla?", "Revisarla con una lista de las cuatro partes", "Así se asegura que esté completa.")],
  [E("¿La publicidad social busca vender?", "No", "Busca el bien común."),
   E("¿Cuáles son las cuatro partes de una evaluación?", "Emisor, intención, destinatario y fundamento", "Completan el análisis."),
   E("¿Qué debe hacer una persona al revisar su evaluación: agregar pistas que faltan o borrar todo?", "Agregar pistas que faltan", "Mejora el fundamento.")],
  ("Revisa este borrador y escríbelo completo: «El aviso del consultorio es bueno». Aviso: «Campaña del Consultorio de Villa Ejemplo: vacúnate contra la influenza. Es gratis y rápido. Imagen: una persona mayor recibiendo una vacuna». Agrega emisor, intención, destinatario y una pista.",
   "El emisor es el Consultorio de Villa Ejemplo. Su intención es que las personas se vacunen. Se dirige a adultos mayores, porque la imagen muestra a una persona mayor vacunándose.",
   ["incluye las cuatro partes", "da una pista del aviso", "no inventa datos"], ["evaluación completa"], ["no dar pistas", "olvidar la intención"],
   "Pide releer la evaluación en voz alta."),
  "Revisa una evaluación tuya con la lista de las cuatro partes.",
  "Escribe un aviso social de tres líneas para tu curso e indica su emisor, intención y destinatario.")

# ================================================================ OA 25 · clase 7
L(OA25, 7,
  "Este cuaderno, lápiz y una hoja. Los mensajes son inventados y vienen escritos.",
  "Aprenderé a aplicar el análisis crítico a otros medios: spot de radio, envase y publicación en redes. Sirve para evaluar la publicidad en cualquier medio donde aparezca.",
  ["Sé evaluar un aviso con cuatro pasos.", "Sé distinguir publicidad comercial y social."],
  ["Los pasos de análisis son los mismos en todos los medios: emisor, intención, destinatario y fundamento. Lo que cambia es la forma. Un spot de radio solo tiene sonido, así que usa la voz, la música y las frases. Un envase tiene dibujos y regalos pensados para quien lo ve en el estante. Una publicación en redes puede venir de una persona conocida que recomienda un producto.",
   "En las redes, a veces una persona famosa recomienda algo. Aunque sea ella quien habla, el emisor del mensaje puede ser la marca que le paga o le da el producto. Por eso las publicaciones pagadas suelen indicar que son publicidad (por ejemplo, con la marca «#publicidad»). Es importante notar esa etiqueta para saber cuándo se trata de un aviso.",
   "Al transferir el análisis, adapta tus preguntas al medio. En radio: ¿qué recurso usa la voz? En el envase: ¿qué atrae a quien lo ve? En redes: ¿quién habla y quién gana si compras? Con estas preguntas puedes evaluar cualquier mensaje publicitario, incluso uno nuevo."],
  [("spot", "aviso breve en radio o televisión"), ("envase", "paquete o caja de un producto"), ("publicación en redes", "mensaje que se difunde en una red social"), ("código de descuento", "palabra o número que da un descuento"), ("etiqueta", "marca que identifica algo, como #publicidad"), ("transferir", "usar lo aprendido en otra situación")],
  [("Spot de radio", f"Lee o escucha: {SPOT} ¿A quién se dirige y qué recurso usa?", ["Empieza con una pregunta al oyente.", "Habla a quienes llegan tarde.", "Usa un problema cotidiano para atraer."], "A quienes les cuesta llegar a tiempo; usa una pregunta inicial sobre un problema."),
   ("Publicación en redes", f"Lee o escucha: {REDES} ¿Cómo sabes que es publicidad?", ["La persona dice sus zapatillas favoritas.", "Ofrece un código de descuento.", "Termina con #publicidad."], "Por la etiqueta #publicidad y el código de descuento.")],
  [("Creer que, si habla una persona famosa, no hay intención comercial.", "La marca puede haberle pagado o regalado el producto.", "Busca la etiqueta #publicidad y pregunta quién gana."),
   ("Cambiar el método según el medio.", "Se pierden pasos importantes.", "Usa siempre emisor, intención, destinatario y fundamento.")],
  ([E(f"Lee o escucha: {SPOT} ¿En qué medio aparece?", "En la radio", "Se llama spot de radio."),
    E(f"Lee o escucha: {SPOT} ¿Qué producto se anuncia?", "Un reloj despertador", "Se llama Despertín."),
    E(f"Lee o escucha: {REDES} ¿Qué código se menciona?", "MIRA10", "Lo dice la publicación.")],
   [E(f"Lee o escucha: {SPOT} ¿A quién se dirige: a personas que llegan tarde o a deportistas?", "A personas que llegan tarde", "Lo dice la primera pregunta."),
    E(f"Lee o escucha: {REDES} ¿Qué indica la etiqueta #publicidad?", "Que el mensaje es un aviso publicitario", "Avisa que es publicidad."),
    E(f"Lee o escucha: {CER} ¿A quién se dirige el envase: a niños o a adultos mayores?", "A niños", "El dinosaurio de regalo y la colección apuntan a ellos.")],
   [E(f"Lee o escucha: {REDES} ¿Qué oferta hace?", "10 % de descuento con un código", "Es el incentivo para comprar."),
    E(f"Lee o escucha: {SPOT} La pregunta inicial «¿Cansado de llegar tarde?», ¿qué recurso es: apelar a un problema del oyente o una exageración?", "Apelar a un problema del oyente", "Conecta con una situación cotidiana."),
    E("¿Cuál de estos medios no puede mostrar imágenes: el spot de radio, el envase o la publicación en redes?", "El spot de radio", "Solo usa sonido.")],
   [E("¿Una persona famosa que recomienda un producto siempre es independiente de la marca?", "No", "La marca puede haberle pagado o regalado el producto."),
    E("¿Se evalúan los avisos de radio y de afiche con los mismos pasos?", "Sí", "Emisor, intención, destinatario y fundamento.")],
   [arith("Unas zapatillas Brisa cuestan $20.000. Con el código MIRA10 se descuenta el 10 %. ¿Cuánto se paga?", "20000-20000//10", "Se resta el descuento del 10 % al precio.", ""),
    E("Un mismo producto se anuncia en radio, afiche y redes. ¿Se mantienen igual el emisor y la intención?", "Sí", "La marca quiere vender en todos.")]),
  [E(f"Lee o escucha: {REDES} Una compañera dice: «La persona famosa recomienda las zapatillas porque le encantan, no hay otra intención». Con la etiqueta #publicidad, ¿qué le respondes?", "Que la publicación es publicidad y busca vender", "La etiqueta lo indica.")],
  [E("¿Qué indica #publicidad en una publicación?", "Que es un aviso publicitario", "Informa al público."),
   E("¿Los cuatro pasos de análisis sirven en todos los medios?", "Sí", "Solo cambian las pistas."),
   E("¿Qué medio no muestra imágenes: la radio o el afiche?", "La radio", "Solo se escucha.")],
  ("Analiza este mensaje con los cuatro pasos y un juicio: «Publicación en redes de un club de lectura (inventado): ¡Únete al Club Lunas de Papel! Nos reunimos los sábados en la biblioteca. Trae un libro para compartir. Es gratis. #invitación». Escribe emisor, intención, destinatario con una pista, y un juicio con una razón.",
   "Emisor: el Club Lunas de Papel. Intención: que más personas se unan al club. Destinatario: personas a quienes les gusta leer; la pista es «trae un libro para compartir». Juicio: parece confiable, porque dice dónde y cuándo se reúnen y que es gratis.",
   ["usa los cuatro pasos", "da una pista", "da un juicio con razón"], ["análisis completo"], ["no fundamentar", "inventar datos"],
   "Pide señalar la frase usada para el destinatario."),
  "Analiza un mensaje que veas en una red social con una persona adulta.",
  "Escribe un spot de radio de cuatro oraciones para una campaña social de tu curso y analízalo.")
